mapper.update:
update t1000_institution 
set del_yn = 'Y' 
where inst_id = #{instId}

mapper.select:
select inst_id, inst_name, to_char(create_dt, 'yyyy-mm-dd') AS create_dt, to_char(update_dt, 'yyyy-mm-dd') AS update_dt, inst_address, inst_phone, inst_post, inst_head_name, inst_detail_address
from t1000_institution
where inst_id=#{instId}
